inline constexpr std::size_t kRecoveredMenuItemsCount =
    sizeof(kRecoveredMenuItems) / sizeof(kRecoveredMenuItems[0]);

inline const char* menuItemBehaviorName(u8 behavior) {
    switch (static_cast<MenuItemBehavior>(behavior)) {
    case MenuItemBehavior::Spacer: return "spacer";
    case MenuItemBehavior::Confirm: return "confirm";
    case MenuItemBehavior::Flash: return "flash";
    }
    return "?";
}

inline std::size_t menuItemCount(std::string_view className,
                                  u32 supplierVa = 0) {
    std::size_t count = 0;
    for (const RecoveredMenuItem& item : kRecoveredMenuItems) {
        if (item.className != className) continue;
        if (supplierVa != 0 && item.supplierVa != supplierVa) continue;
        ++count;
    }
    return count;
}

inline const RecoveredMenuItem* findMenuItem(std::string_view className,
                                               u16 index,
                                               u32 supplierVa = 0) {
    for (const RecoveredMenuItem& item : kRecoveredMenuItems) {
        if (item.className != className || item.index != index) continue;
        if (supplierVa != 0 && item.supplierVa != supplierVa) continue;
        return &item;
    }
    return nullptr;
}

inline bool hasMenuItemLabel(std::string_view label) {
    for (const RecoveredMenuItem& item : kRecoveredMenuItems)
        if (item.label == label) return true;
    return false;
}

